{
  "$comment": "Component inventory (dfw system phase). One entry per component the product needs, derived from PRODUCT.md workflows and the screen blueprints, never from a kit list. name = master file name; purpose = the job it does in THIS product; usedBy = pages/screens that need it; states = every state its CSS must cover; ref = optional kit reference consulted with \"dfw system ref <name>\" (a checklist, never copied).",
  "components": []
}

