/* Generated by dfw from design/system/components/*.html. Do not edit by hand. */

/* button (design/system/components/button.html) */
.btn { display: inline-flex; align-items: center; height: 40px; padding: 0 var(--space-4); border-radius: var(--radius-md); border: 1px solid transparent; font: inherit; }
.btn--primary { background: var(--color-accent); color: var(--color-on-accent); }
.btn--ghost { background: transparent; color: var(--color-ink); border-color: var(--color-border); }
.btn:focus-visible { outline: 2px solid var(--color-accent); }

/* motif (design/system/components/motif.html) */
/* Motifs belong to the "heritage-signboard" style. While comparing other option themes, decorative motifs
   are hidden and motifs with content fall back to plain text (content never disappears). */
[data-theme^="opt-"]:not([data-theme="opt-heritage-signboard"]) .motif:empty { display: none; }
[data-theme^="opt-"]:not([data-theme="opt-heritage-signboard"]) .motif:not(:empty) { all: unset; font-family: var(--font-family-mono); font-size: var(--font-size-sm); color: var(--color-muted); }
.motif--signboard-frame { background: var(--color-brand); color: var(--color-on-brand); padding: var(--space-8); outline: var(--border-width-strong) solid var(--color-signature); outline-offset: calc(var(--space-2) * -1); }
.motif--gold-rule { display: flex; align-items: center; gap: var(--space-2); color: var(--color-signature); } .motif--gold-rule::before, .motif--gold-rule::after { content: ""; height: 1px; width: var(--space-12); background: currentColor; } .motif--gold-rule > span { width: var(--space-1-5); height: var(--space-1-5); background: currentColor; transform: rotate(45deg); }

